{
  "a_sentences": [
    {
      "a_text": "Selon les constatations cantonales non arbitraires, les parents de la personne assurée étaient informés au moins en 2003 de l'influence de la G.________ sur l'état de santé de l'enfant, ce qui exclut une situation évolutive empêchant de se faire une idée du dommage.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Le début de l'accouchement marque le moment à partir duquel la vie humaine est protégée par le droit pénal.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Lorsque l'ampleur du préjudice résulte d'une situation évolutive, le délai de prescription ne court pas avant le terme de cette évolution.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Tel est notamment le cas du préjudice consécutif à une atteinte à la santé dont l'évolution ne peut être prévue d'emblée avec suffisamment de certitude.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "L'art. 122 CP réprime quiconque intentionnellement blesse une personne de façon à mettre sa vie en danger, mutile un membre ou un organe important, cause une incapacité de travail, une infirmité ou une maladie mentale permanente, ou fait subir toute autre atteinte grave à l'intégrité corporelle ou à la santé.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "L'acte illicite supposé étant intervenu durant la grossesse, le délai absolu de dix ans a commencé à courir au plus tard à la naissance et est arrivé à échéance le 8 août 2011.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "En l'état du droit, une poursuite pénale n'est pas ouverte pour une atteinte portée à un embryon ou à un foetus nonobstant sa naissance vivante ultérieure.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "C'est à bon escient que la juridiction cantonale n'a pas appliqué la prescription de plus longue durée prévue par le droit pénal.",
      "b_propositions": ["P8"]
    }
  ]
}
